import * as React from 'react';

export type PulseIconProps = React.SVGProps<SVGSVGElement> & { size?: number; title?: string };

function make(name: string, label: string, body: React.ReactNode) {
  const C = ({ size = 24, title, strokeWidth = 2, ...rest }: PulseIconProps) => (
    <svg xmlns="http://www.w3.org/2000/svg" width={size} height={size} viewBox="0 0 24 24" fill="none"
      stroke="currentColor" strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round"
      role={title ? 'img' : undefined} aria-hidden={title ? undefined : true} {...rest}>
      {title ? <title>{title}</title> : null}
      {body}
    </svg>
  );
  C.displayName = name;
  (C as any).label = label;
  return C;
}

